import { act, render, screen, waitFor } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn().mockResolvedValue({ isError: false }),
	connect: vi.fn().mockResolvedValue(undefined),
	hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() {
			return { theme: "light", ...bridge.hostContext };
		}
		async openLink() { return { isError: false }; }
	},
	PostMessageTransport: class { async close() {} },
}));

describe("stale restore probe", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.hostContext = {
			toolInfo: { id: "reused-id", tool: { name: "query_sdk" } },
		};
	});

	it("does not apply the first card restore after an identical second result reuses its identity", async () => {
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: Object.assign(new EventTarget(), {
				location: { origin: "https://portable-host.example" },
			}),
		});
		let resolveRestore!: (value: unknown) => void;
		const firstRestore = new Promise((resolve) => { resolveRestore = resolve; });
		let restoreCount = 0;
		bridge.callServerTool.mockImplementation(async ({ name }) => {
			if (name === "restore_lobu_app_result") {
				restoreCount += 1;
				if (restoreCount === 1) return firstRestore;
				return { isError: false, structuredContent: { found: false, view_state: {} } };
			}
			return { isError: false, structuredContent: { saved: false } };
		});

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, viewState } = useMcpApp<{ title: string }>();
			return <><span>{data?.title ?? "none"}</span><span>open:{String(viewState["details.open"])}</span></>;
		}
		render(<Provider devMock={{ title: "dev" }}><Probe /></Provider>);
		await waitFor(() => expect(restoreCount).toBe(1));

		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({ structuredContent: { title: "identical" } });
			}
		});
		expect(await screen.findByText("identical")).toBeInTheDocument();

		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({ structuredContent: { title: "identical" } });
			}
			for (const handler of bridge.listeners.get("hostcontextchanged") ?? []) {
				handler({ theme: "light" });
			}
		});

		await act(async () => {
			resolveRestore({
				isError: false,
				structuredContent: {
					found: true,
					tool_name: "query_sdk",
					data: { title: "identical" },
					view_state: { "details.open": true },
				},
			});
			await firstRestore;
		});

		expect(screen.getByText("open:undefined")).toBeInTheDocument();
	});
});

